import axios from "axios";

// Correct the API_BASE_URL to match your backend URL
const API_BASE_URL = "http://localhost:5000/api/delivery"; // Adjusted to match the backend URL

// Fetch all deliveries
export const fetchDeliveries = () => axios.get(`${API_BASE_URL}`);

// Assign a driver to a delivery
export const assignDriver = (deliveryId: string, driverId: string) =>
  axios.put(`${API_BASE_URL}/${deliveryId}/assign`, { driverId });

// Get a delivery by its ID
export const getDeliveryById = (id: string) =>
  axios.get(`${API_BASE_URL}/${id}`);
